# Garde Manger and Preservation (cugarde): lessons. No home curing recipes: curing needs exact curing salts and
# controlled rooms, so it is described, not taught as a recipe. Canning only by tested recipes (USDA / NCHFP).
LESSONS = {
"salads-dressings": LES([
 P("The <b>garde manger</b> (gard mahn-ZHAY, \"keeper of the food\") runs the cold kitchen: salads, dressings, cold appetizers, pâtés, cured foods and cheese."),
 K("<b>Greens:</b> wash in plenty of cold water, lift them out (grit sinks), and dry them completely, ideally in a salad spinner. Dress <b>just before serving</b>, lightly, and toss so every leaf is coated. <b>Dressings:</b> a basic vinaigrette is about 3 parts oil to 1 part acid with salt; <b>emulsified dressings</b> (mayonnaise-based, or with mustard or yolk) stay mixed; creamy dressings use dairy."),
 LI("Keep everything cold: greens, plates and dressings.",
    "Tear or cut greens into bite sizes; remove tough ribs.",
    "Season the salad, not just the dressing: a pinch of salt on the leaves helps.",
    "Composed salads (arranged, such as a Niçoise) are plated piece by piece; tossed salads are mixed."),
 SAFE("Cut leafy greens and cut tomatoes are TCS foods under the Food Code: keep them at 41°F or below.", "Wash produce under running water; don't use soap on food."),
 W("Oil clings to dry leaves. Water on the leaves keeps oil from sticking, so dressing slides off and pools in the bowl."),
 EX("Scale a vinaigrette", "You need 2 cups of 3 : 1 vinaigrette. How much vinegar?", ["One part is $2 \\div 4 = 0.5$ cup."], "½ cup vinegar (1½ cups oil)."),
 M("Dressing a salad an hour early. Acid and salt wilt the leaves."),
 DRILL("Make three vinaigrettes with different acids (red wine vinegar, lemon, sherry vinegar). Taste each on a plain leaf of lettuce.", "Make the original 1896 Waldorf salad from Meal Prep."),
 MP([("scratch/vinaigrette/", "Italian-style vinaigrette", ""), ("scratch/ranch-dressing/", "Ranch dressing", ""), ("recipes/original-waldorf-salad/", "The Original Waldorf Salad (1896)", ""), ("recipes/celery-victor/", "Celery Victor", "a cold salad from San Francisco")]),
 TRY,
], "g_garde", "foodcode"),

"canapes": LES([
 P("Canapés and hors d'oeuvres are the small bites at the start of a party or a meal. They are made in quantity, so speed and evenness count."),
 K("A <b>canapé</b> has three parts: a <b>base</b> (toast, cracker, pastry, cucumber round), a <b>spread</b> (flavored butter, cream cheese, mousse) that also keeps the base from going soggy, and a <b>garnish</b> on top. It should be one or two bites. <b>Hors d'oeuvres</b> is the broader word for small appetizers, hot or cold."),
 LI("Plan about 4 to 6 pieces per person for a short reception before dinner, more for a party that replaces a meal (a common catering guide).",
    "Prep components ahead; assemble close to service.",
    "Arrange in neat rows on trays; make every piece the same."),
 SAFE("Cold canapés stay at 41°F or below until served; under the Food Code, food served without temperature control must follow the code's time limits (for cold food, up to 6 hours if it starts at 41°F or below and never goes above 70°F; for hot or cold, 4 hours) and is then thrown away."),
 W("A spread of fat (butter or cream cheese) acts as a barrier between a wet topping and a crisp base. That is why classic canapés start with butter on the toast."),
 EX("How many?", "A reception for 40 people at 5 pieces per person, with 4 kinds of canapé. How many of each kind?", ["$40 \\times 5 = 200$ pieces.", "$200 \\div 4 = 50$ of each."], "50 of each kind."),
 M("Building canapés on bread hours ahead; they go soft."),
 DRILL("Make 24 identical canapés of one kind. Line them up and look for the odd ones out. Then make 24 more, faster."),
 MP([("recipes/melba-toast/", "Melba Toast", "a crisp base, named for Nellie Melba")]),
 TRY,
], "g_garde", "foodcode"),

"pickles": LES([
 P("Quick pickles take minutes to make and keep for weeks in the refrigerator. Shelf-stable canning is a different, stricter skill."),
 K("<b>Quick (refrigerator) pickles:</b> vegetables packed in a jar and covered with a hot or cold brine of vinegar, water, salt and often sugar and spices, then <b>kept in the refrigerator</b>. A common brine is equal parts vinegar and water. <b>Canned pickles</b> kept on a shelf must follow a <b>tested recipe</b> from the USDA or a university extension service (such as the National Center for Home Food Preservation), exactly, because the acidity and processing time are what keep them safe."),
 LI("Use vinegar of at least 5% acidity (it says so on the label).",
    "Use pickling or canning salt, or kosher salt without additives, measured by weight.",
    "Don't reduce the vinegar in a canning recipe; you can reduce sugar in some quick pickles.",
    "Fermented pickles (like sauerkraut) are made a third way, by bacteria making acid; follow a tested recipe."),
 W("Acid stops the growth of the germs that matter most in sealed jars, including the one that causes botulism. In a refrigerator pickle, cold adds a second barrier; on a shelf, only correct acidity and processing protect you."),
 EX("Brine", "A quick pickle brine is 1 : 1 vinegar to water. How much of each for 3 cups of brine?", ["Half of 3 cups each."], "1½ cups vinegar and 1½ cups water."),
 M("Inventing a low-vinegar recipe and storing it on the shelf."),
 DRILL("Make quick-pickled red onions: slice thin, cover with hot 1 : 1 vinegar and water with a pinch of salt and sugar, cool, refrigerate. Taste after 1 hour and after 1 day."),
 MP([("scratch/refrigerator-pickles/", "Refrigerator dill pickles", "a refrigerator pickle, step by step")]),
 TRY,
], "nchfp", "g_pickling"),

"confit-terrines": LES([
 P("Before refrigerators, French cooks preserved meat by cooking it slowly in fat and sealing it under that fat. Today confit is made for its flavor and texture, and kept cold."),
 K("<b>Confit</b> (kohn-FEE): meat, usually duck legs, salted for a day, then cooked very slowly submerged in fat until meltingly tender, then stored in the fat in the refrigerator. <b>Pâté</b> is a seasoned paste of meat, liver or fish; a <b>terrine</b> is a pâté (or layered vegetables) cooked in a mold, often in a water bath, pressed, chilled and sliced. A <b>forcemeat</b> is the mixture of ground meat, fat and seasoning they are made from."),
 LI("Terrines are cooked to a safe internal temperature for their meat (165°F if they contain poultry).",
    "Cool by the two-stage rule, then keep refrigerated; slice cold with a hot, wet knife.",
    "Keep forcemeats very cold while grinding and mixing so the fat doesn't smear.",
    "Confit and terrines are refrigerated foods; the covering of fat is not a reason to keep them at room temperature."),
 W("Fat seals out air but not every germ; some dangerous ones grow without air. Modern guidance treats confit and terrines as refrigerated, ready-to-eat foods with the usual 7-day date-marking limit in restaurants."),
 EX("Date mark", "A chicken liver terrine is made on day 1 and kept at 41°F. On which day must it be used or discarded at the latest?", ["Ready-to-eat TCS food: 7 days, with the day it was made as day 1."], "Day 7."),
 M("Keeping confit in a cupboard \"like in the old days\". Keep it in the refrigerator."),
 DRILL("Make a simple vegetable terrine (layers of roasted vegetables pressed in a loaf pan lined with plastic wrap). Chill overnight, unmold and slice it neatly."),
 TRY,
], "g_confit", "foodcode"),

"charcuterie-cheese": LES([
 P("<b>Charcuterie</b> (shar-KOO-tuh-ree) means prepared meats: sausages, hams, pâtés, terrines and dry-cured salami. Many of them are made by curing, which takes exact measurements and controlled conditions."),
 K("<b>Curing</b> preserves meat with salt and, for most cured meats, a measured amount of <b>curing salt</b> (sodium nitrite or nitrate). <b>Dry-cured</b> products such as prosciutto and salami are then dried for weeks or months in rooms with controlled temperature and humidity. That is why this lesson describes curing rather than teaching a recipe: the amounts must be exact, and commercial producers work under inspection with tested processes. You can buy well-made cured meats and build a board."),
 LI("<b>A board:</b> two or three cured meats (one whole-muscle like prosciutto, one salami, one pâté), three cheeses of different kinds, something sweet (fruit, jam), something sharp (pickles, mustard), and bread or crackers.",
    "<b>Cheese families:</b> fresh (ricotta, mozzarella), soft-ripened (brie), semi-soft (fontina), semi-hard (cheddar, Gruyère), hard (Parmesan), blue.",
    "Serve cheese at cool room temperature for the best flavor; take it out about 30 minutes ahead.",
    "Slice cured meats thin; cut cheeses so each piece has some rind and some center."),
 SAFE("Serve a board within the time the Food Code allows without temperature control, or keep it chilled, and put out small amounts at a time.", "Label boards for allergens: nuts, milk, wheat and sesame are common on them."),
 W("Salt pulls water out of meat and makes it hard for germs to grow. Nitrite adds protection, especially against the germ that causes botulism, and gives cured meat its pink color. Too little is unsafe and too much is harmful, which is why it's always measured to a tested recipe."),
 EX("Cheese count", "A board for 12 people at about 1 ounce of cheese per person per kind, with 3 cheeses. How many ounces of each?", ["12 people × 1 ounce = 12 ounces of each."], "12 ounces of each cheese."),
 M("Trying to dry-cure sausage at home by guesswork."),
 DRILL("Build a board for four from store-bought cured meats and cheeses, following the list above. Name each cheese's family."),
 MP([("scratch/ricotta/", "Fresh ricotta-style cheese", "a fresh cheese you can make safely at home")]),
 TRY,
], "g_charc", "foodcode"),
}
